# Preserve the proven 3.0.58 scanner behavior first.
runpy.run_path('.github/prepare_3058.py', run_name='__main__')

p=Path('app/src/main/java/com/iceinventory/onhand/MainActivity.java')
s=p.read_text()

# Saved operator name and protected zero-all PIN.
old='''    private static final String KEY_COMPACT="compact_list";\n'''
new='''    private static final String KEY_COMPACT="compact_list";\n    private static final String KEY_USER_NAME="export_user_name";\n    private static final String KEY_ZERO_PIN="zero_all_pin";\n'''
if old not in s: raise SystemExit('3.0.59 target missing: settings keys')
