new='''        box.addView(optionSwitch("Compact List View",KEY_COMPACT,true));\n        TextView operator=text("User / Export",16,gold(),true);operator.setPadding(dp(6),dp(8),0,dp(2));box.addView(operator);\n        Button userNameButton=button(userNameButtonLabel(),0);\n        userNameButton.setOnClickListener(v->promptUserName(false));\n        box.addView(userNameButton,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(50)));\n'''
