# Replace the old unprotected Zero All confirmation with a required 4-digit passcode flow.
old='''    private void confirmZeroAllQuantities() {\n        new AlertDialog.Builder(this)\n                .setTitle("Zero All Quantities?")\n                .setMessage("This sets every quantity in the current inventory to 0. Barcodes, descriptions, prices and locations will remain unchanged.")\n                .setPositiveButton("ZERO ALL",(d,w)->{\n                    int changed=db.zeroAllQuantities(sessionId);\n                    refreshList();\n                    toast("Zeroed quantities for "+changed+" item lines");\n                })\n                .setNegativeButton("Cancel",null)\n                .show();\n    }\n\n'''
new='''    private String savedUserName() {\n        String n=prefs().getString(KEY_USER_NAME,"");\n        return n==null?"":n.trim();\n    }\n\n    private String userNameButtonLabel() {\n        String n=savedUserName();\n        return n.isEmpty()?"Set User Name":"User Name: "+n;\n    }\n\n    private void promptUserName(boolean continueExport) {\n        EditText input=new EditText(this);\n        input.setSingleLine(true);\n        input.setHint("User name");\n        input.setText(savedUserName());\n        if(input.getText().length()>0)input.setSelection(input.getText().length());\n        AlertDialog dialog=new AlertDialog.Builder(this)\n                .setTitle("User Name")\n                .setMessage("This name is saved on this device and added automatically to every export filename.")\n                .setView(input)\n                .setPositiveButton("Save",null)\n                .setNegativeButton("Cancel",null)\n                .create();\n        dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{\n            String n=input.getText().toString().trim();\n            if(n.isEmpty()){toast("Enter a user name");return;}\n            prefs().edit().putString(KEY_USER_NAME,n).apply();\n            dialog.dismiss();\n            toast("User name saved: "+n);\n            if(continueExport)showExportDialog();\n        }));\n        dialog.show();\n    }\n\n    private String zeroPinButtonLabel() {\n        String p=prefs().getString(KEY_ZERO_PIN,"");\n        return validZeroPin(p)?"Change Zero Passcode":"Set 4-Digit Zero Passcode";\n    }\n\n    private boolean validZeroPin(String pin) {\n        return pin!=null&&pin.matches("\\\\d{4}");\n    }\n\n    private EditText zeroPinEntry(String hint) {\n        EditText input=new EditText(this);\n        input.setSingleLine(true);\n        input.setHint(hint);\n        input.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);\n        input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(4)});\n        return input;\n    }\n\n    private void confirmZeroAllQuantities() {\n        String saved=prefs().getString(KEY_ZERO_PIN,"");\n        if(!validZeroPin(saved)){setupZeroPasscode(true);return;}\n        EditText input=zeroPinEntry("4-digit passcode");\n        AlertDialog dialog=new AlertDialog.Builder(this)\n                .setTitle("Enter Zero Passcode")\n                .setMessage("Enter the 4-digit passcode to continue.")\n                .setView(input)\n                .setPositiveButton("Continue",null)\n                .setNegativeButton("Cancel",null)\n                .create();\n        dialog.setOnShowListener(x->{\n            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{\n                String entered=input.getText().toString();\n                if(!saved.equals(entered)){toast("Incorrect passcode");input.selectAll();return;}\n                dialog.dismiss();\n                showZeroAllFinalConfirmation();\n            });\n            input.requestFocus();input.postDelayed(()->showKeyboard(input),80);\n        });\n        dialog.show();\n    }\n\n    private void setupZeroPasscode(boolean continueZero) {\n        EditText first=zeroPinEntry("New 4-digit passcode");\n        AlertDialog dialog=new AlertDialog.Builder(this)\n                .setTitle("Create Zero Passcode")\n                .setMessage("Choose exactly 4 digits. This passcode will be required before all inventory quantities can be zeroed.")\n                .setView(first)\n                .setPositiveButton("Next",null)\n                .setNegativeButton("Cancel",null)\n                .create();\n        dialog.setOnShowListener(x->{\n            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{\n                String pin=first.getText().toString();\n                if(!validZeroPin(pin)){toast("Passcode must be exactly 4 digits");first.selectAll();return;}\n                dialog.dismiss();\n                confirmNewZeroPasscode(pin,continueZero);\n            });\n            first.requestFocus();first.postDelayed(()->showKeyboard(first),80);\n        });\n        dialog.show();\n    }\n\n    private void confirmNewZeroPasscode(String pin,boolean continueZero) {\n        EditText second=zeroPinEntry("Confirm 4-digit passcode");\n        AlertDialog dialog=new AlertDialog.Builder(this)\n                .setTitle("Confirm Zero Passcode")\n                .setView(second)\n                .setPositiveButton("Save",null)\n                .setNegativeButton("Cancel",null)\n                .create();\n        dialog.setOnShowListener(x->{\n            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{\n                if(!pin.equals(second.getText().toString())){toast("Passcodes do not match");second.selectAll();return;}\n                prefs().edit().putString(KEY_ZERO_PIN,pin).apply();\n                dialog.dismiss();\n                toast("4-digit zero passcode saved");\n                if(continueZero)showZeroAllFinalConfirmation();\n            });\n            second.requestFocus();second.postDelayed(()->showKeyboard(second),80);\n        });\n        dialog.show();\n    }\n\n    private void changeZeroPasscode() {\n        String saved=prefs().getString(KEY_ZERO_PIN,"");\n        if(!validZeroPin(saved)){setupZeroPasscode(false);return;}\n        EditText current=zeroPinEntry("Current 4-digit passcode");\n        AlertDialog dialog=new AlertDialog.Builder(this)\n                .setTitle("Change Zero Passcode")\n                .setView(current)\n                .setPositiveButton("Continue",null)\n                .setNegativeButton("Cancel",null)\n                .create();\n        dialog.setOnShowListener(x->{\n            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{\n                if(!saved.equals(current.getText().toString())){toast("Incorrect passcode");current.selectAll();return;}\n                dialog.dismiss();setupZeroPasscode(false);\n            });\n            current.requestFocus();current.postDelayed(()->showKeyboard(current),80);\n        });\n        dialog.show();\n    }\n\n    private void showZeroAllFinalConfirmation() {\n        new AlertDialog.Builder(this)\n                .setTitle("Zero All Quantities?")\n                .setMessage("This sets every quantity in the current inventory to 0. Barcodes, descriptions, prices and locations will remain unchanged.")\n                .setPositiveButton("ZERO ALL",(d,w)->{\n                    int changed=db.zeroAllQuantities(sessionId);\n                    refreshList();\n                    toast("Zeroed quantities for "+changed+" item lines");\n                })\n                .setNegativeButton("Cancel",null)\n                .show();\n    }\n\n'''
if old not in s: raise SystemExit('3.0.59 target missing: zero-all method')
s=s.replace(old,new,1)

# Export requires a saved user name and automatically prefixes it to the imported/session filename.
old='''    private void showExportDialog() {\n        EditText name=new EditText(this);\n'''
new='''    private void showExportDialog() {\n        String exportUser=savedUserName();\n        if(exportUser.isEmpty()){promptUserName(true);return;}\n        EditText name=new EditText(this);\n'''
if old not in s: raise SystemExit('3.0.59 target missing: export dialog start')
s=s.replace(old,new,1)

old='''        String defaultName=prefs().getString(importFileNameKey(),"");\n        if(defaultName==null||defaultName.trim().isEmpty())defaultName=safeFileName(sessionName)+".txt";\n        name.setText(cleanTextName(defaultName));\n'''
new='''        String defaultName=prefs().getString(importFileNameKey(),"");\n        if(defaultName==null||defaultName.trim().isEmpty())defaultName=sessionName+".txt";\n        name.setText(userExportFileName(exportUser,defaultName));\n'''
if old not in s: raise SystemExit('3.0.59 target missing: export default name')
s=s.replace(old,new,1)

marker='''    private String cleanTextName(String s) {\n'''
helpers='''    private String userExportFileName(String user,String base) {\n        String u=safeFilePart(user);\n        String b=base==null?"":base.trim();\n        if(b.toLowerCase(Locale.US).endsWith(".txt"))b=b.substring(0,b.length()-4);\n        b=safeFilePart(b);\n        if(b.isEmpty())b=safeFilePart(sessionName);\n        return cleanTextName(u+" - "+b);\n    }\n\n    private String safeFilePart(String s) {\n        String n=s==null?"":s.trim();\n        return n.replaceAll("[\\\\/:*?\\\"<>|]+","_").replaceAll("\\\\s+"," ").trim();\n    }\n\n'''
if marker not in s: raise SystemExit('3.0.59 target missing: cleanTextName marker')
s=s.replace(marker,helpers+marker,1)

